1639	/** Build a WP with proper sequential timestamps for temporal-guard tests */
1640	function makeWpTimed(
1641	  id: string,
1642	  status: string,
1643	  pipelines: Array<{ type: string; status: string }>,
1644	  deps: string[] = []
1645	): WorkPackageDetail {
1646	  const base = new Date('2026-01-01T08:00:00').getTime();
1647	  return {
1648	    work_package_id: id,
1649	    work_package_file: `work/${id}.md`,
1650	    status: status as any,
1651	    assigned_to: 'Developer',
1652	    dependencies: deps,
1653	    acceptance_criteria: [],
1654	    revision: 0,
1655	    pipelines: pipelines.map((p, i) => {
1656	      if (p.status === 'IN_PROGRESS') {
1657	        return { type: p.type, status: p.status as any, summary: [], started_at: new Date(base + i * 3600000).toISOString() };
1658	      }
1659	      const startMs = base + i * 3600000;
1660	      const endMs = startMs + 30 * 60 * 1000;
1661	      return {
1662	        type: p.type,
1663	        status: p.status as any,
1664	        summary: [],
1665	        started_at: new Date(startMs).toISOString(),
1666	        completed_at: new Date(endMs).toISOString(),
1667	      };
1668	    }),
1669	  };
1670	}
